        data: {"result": {"minY": 1.0, "minX": 0.0, "maxY": 250.0, "series": [{"data": [[0.0, 136.0], [100.0, 12.0], [200.0, 2.0]], "isOverall": false, "label": "Blockchain Status", "isController": false}, {"data": [[0.0, 191.0], [100.0, 9.0]], "isOverall": false, "label": "Health Check", "isController": false}, {"data": [[0.0, 189.0], [100.0, 11.0]], "isOverall": false, "label": "Poll Status", "isController": false}, {"data": [[0.0, 250.0]], "isOverall": false, "label": "Submit Vote", "isController": false}, {"data": [[0.0, 169.0], [300.0, 2.0], [100.0, 18.0], [200.0, 8.0], [400.0, 1.0], [500.0, 2.0]], "isOverall": false, "label": "Get Results", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 500.0, "title": "Response Time Distribution"}},
